insert into admin_announcements (id, target_role, message, message_bn, urgency, sent_at, sent_by_admin_id) values
  ('ann00000-0000-4000-8000-000000009300', 'providers', 'Heavy rain expected across Dhaka tomorrow. Update your availability if you cannot travel.', 'আগামীকাল ঢাকায় ভারী বৃষ্টির সম্ভাবনা। যাতায়াত করতে না পারলে আপনার সময়সূচি আপডেট করুন।', 'urgent', '2026-09-07T13:23:16.790Z', 'admin'),
  ('ann00000-0000-4000-8000-000000009301', 'customers', 'Rate your completed jobs to unlock discount coupons on your next booking.', 'পরবর্তী বুকিংয়ে ছাড়ের কুপন পেতে সম্পন্ন কাজগুলোতে রেটিং দিন।', 'normal', '2026-09-02T13:23:16.790Z', 'admin')
