  ('issue000-0000-4000-8000-000000009200', 'book0000-0000-4000-8000-000000000002', 'cust0000-0000-4000-8000-000000000008', 'Provider arrived 90 minutes after the agreed slot.', 'open', null, '2026-09-06T13:23:16.790Z'),
  ('issue000-0000-4000-8000-000000009201', 'book0000-0000-4000-8000-000000000012', 'cust0000-0000-4000-8000-000000000010', 'Problem came back the next day, work was not durable.', 'open', null, '2026-09-05T13:23:16.790Z'),
  ('issue000-0000-4000-8000-000000009202', 'book0000-0000-4000-8000-000000000022', 'cust0000-0000-4000-8000-000000000009', 'Charged more than the quoted price at the door.', 'escalated', null, '2026-09-04T13:23:16.790Z')
